    'phpVersionError' => 'Tu servidor debe tener <strong>PHP 7.2.0 o superior</strong> instalado para ejecutar tu foro.<br/><small>Actualiza tu instalación de PHP o solicita a tu proveedor de hosting o administrador que actualicen el servidor.</small>',
    'mysqliError' => 'Debes tener instalado <strong>MySQL 5.7 o superior</strong> y la <a href=\'https://php.net/manual/en/mysqli.installation.php\' target=\'_blank\'>extensión MySQLi habilitada en PHP</a>.<br/><small>Instala/actualiza ambos requisitos o solicita a tu proveedor de hosting o administrador que los instalen.</small>',
    'filePermissionsError' => 'Los siguientes archivos/carpetas no son escribibles: <strong>%s</strong>.<br/><small>
