/* Spanish gambits: visible labels and parser tokens. */
$language['gambits'] = array(
  '100' => '100', 'tag:' => 'etiqueta:', 'author:' => 'autor:', 'contributor:' => 'participante:',
  'member' => 'miembro', 'myself' => 'yo', 'draft' => 'borrador', 'has' => 'tiene', 'post' => 'mensaje',
  'has attachments' => 'tiene adjuntos', 'limit:' => 'límite:', 'locked' => 'bloqueado',
  'order by newest' => 'ordenar por más recientes', 'order by posts' => 'ordenar por número de mensajes',
  'private' => 'privado', 'random' => 'aleatorio', 'reverse' => 'invertir', 'starred' => 'marcado',
  'sticky' => 'fijado', 'unread' => 'no leído', 'more results' => 'más resultados', 'active today' => 'activo hoy',
  'active 1 day' => 'activo 1 día', 'has replies' => 'tiene respuestas', 'has &gt; 1 post' => 'tiene &gt; 1 mensaje',
  'has no replies' => 'no tiene respuestas', 'has 0 posts' => 'tiene 0 mensajes', 'dead' => 'inactivo',
  'active &gt; 30 day' => 'activo &gt; 30 días', 'second' => 'segundo', 'seconds' => 'segundos', 'minute' => 'minuto', 'minutes' => 'minutos',
  'hour' => 'hora', 'hours' => 'horas', 'day' => 'día', 'days' => 'días', 'week' => 'semana', 'weeks' => 'semanas',
  'month' => 'mes', 'months' => 'meses', 'year' => 'año', 'years' => 'años',
  'last' => 'último', 'active' => 'activo',
);
$language['gambits'] += array(
  'gambitActive' => "/^{$language['gambits']['active']} *(?<a>&gt;|&lt;|&gt;=|&lt;=|{$language['gambits']['last']})? *(?<b>\\d+) *(?<c>{$language['gambits']['second']}|{$language['gambits']['seconds']}|{$language['gambits']['minute']}|{$language['gambits']['minutes']}|{$language['gambits']['hour']}|{$language['gambits']['hours']}|{$language['gambits']['day']}|{$language['gambits']['days']}|{$language['gambits']['week']}|{$language['gambits']['weeks']}|{$language['gambits']['month']}|{$language['gambits']['months']}|{$language['gambits']['year']}|{$language['gambits']['years']})/",
  'active last ? hours' => "{$language['gambits']['active']} {$language['gambits']['last']} ? {$language['gambits']['hour']}s",
  'active last ? days' => "{$language['gambits']['active']} {$language['gambits']['last']} ? {$language['gambits']['day']}s",
  'gambitHasNPosts' => "/^{$language['gambits']['has']} *(?<a>&gt;|&lt;|&gt;=|&lt;=)? *(?<b>\\d+) *{$language['gambits']['post']}s?/",
